# v1.8 login page on the REAL server (fresh DB, port 8800)
from playwright.sync_api import sync_playwright
B='http://127.0.0.1:8800/';OWN='Sunrise-Tea-4471';res=[]
def ok(c,m): res.append(('PASS ' if c else 'FAIL ')+m)
with sync_playwright() as p:
    b=p.chromium.launch();errs=[];pg=b.new_context(viewport={'width':390,'height':800}).new_page();pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto(B+'admin/login.html');pg.wait_for_selector('#lu')
    t=pg.inner_text('main.login')
    ok('Staff sign-in' in t and ('Good' in t or 'Welcome' in t),'brand header with a greeting')
    ok(pg.locator('details.tips').count()==1,'sign-in tips are shown')
    ok(pg.evaluate("document.documentElement.scrollWidth<=window.innerWidth"),'no sideways scrolling on a phone')
    pg.fill('#lu','owner');pg.fill('#lp','wrong-password-1');pg.click('button.btn')
    pg.wait_for_selector('#lmsg:not(:empty)');ok('Wrong username or password' in pg.inner_text('#lmsg'),'wrong password shows the server message')
    ok(pg.get_attribute('#lp','aria-invalid')=='true' and pg.input_value('#lp')=='' and pg.evaluate("document.activeElement.id")=='lp','password field is flagged, cleared and focused')
    ok(pg.inner_text('button.btn')=='Log in' and not pg.is_disabled('button.btn'),'button is ready again after an error')
    pg.fill('#lp',OWN)
    pg.evaluate("window.__seen=[];new MutationObserver(()=>window.__seen.push(document.querySelector('button.btn').textContent)).observe(document.querySelector('button.btn'),{childList:true,characterData:true,subtree:true})")
    pg.click('button.btn');pg.wait_for_url('**/admin/index.html');ok(True,'sign-in works')
    pg.goto(B+'admin/login.html');pg.wait_for_selector('#lu');ok(pg.locator('button.linkbtn').count()==1 and pg.input_value('#lu')=='owner','remembered user shows "Not you?"')
    pg.click('button.linkbtn');ok(pg.input_value('#lu')=='' and pg.evaluate("localStorage.getItem('mc_lastuser')")is None,'"Not you?" clears the remembered name')
    pg.context.set_offline(True);pg.evaluate("window.dispatchEvent(new Event('offline'))");ok(pg.locator('main.login p[role=status]').first.is_visible() or pg.locator('text=You are offline').is_visible(),'offline notice appears');pg.context.set_offline(False)
    pg.evaluate("localStorage.setItem('mc_lang','bn')");pg.reload();pg.wait_for_selector('#lu');ok('স্টাফ সাইন-ইন' in pg.inner_text('main.login'),'Bangla brand header');pg.evaluate("localStorage.removeItem('mc_lang')")
    ok(not errs,'no page errors '+str(errs[:2]));b.close()
print('\n'.join(res));print('SUMMARY pass=%d fail=%d'%(sum(r.startswith('PASS') for r in res),sum(r.startswith('FAIL') for r in res)))
